CREATE TABLE flash_sale_activity (id BIGINT NOT NULL AUTO_INCREMENT,code VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,edition_id BIGINT NOT NULL,region_code VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,currency CHAR(3) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,sale_price_minor BIGINT NOT NULL,total_stock BIGINT NOT NULL,allocated_stock BIGINT NOT NULL DEFAULT 0,status VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'draft',starts_at DATETIME(6) NOT NULL,ends_at DATETIME(6) NOT NULL,payment_timeout_seconds INT NOT NULL DEFAULT 900,version BIGINT NOT NULL DEFAULT 0,created_by BIGINT NOT NULL,activated_at DATETIME(6) NULL,cancelled_at DATETIME(6) NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),PRIMARY KEY(id),CONSTRAINT uk_flash_sale_activity_code UNIQUE(code),KEY idx_flash_sale_activity_window(status,starts_at,ends_at,id),KEY idx_flash_sale_activity_scope_window(edition_id,region_code,currency,status,starts_at,ends_at,id),KEY idx_flash_sale_activity_edition(edition_id,created_at DESC,id DESC),KEY idx_flash_sale_activity_creator(created_by),CONSTRAINT ck_flash_sale_activity_code CHECK(REGEXP_LIKE(code,'^[A-Z0-9-]{3,64}$','c')),CONSTRAINT ck_flash_sale_activity_region CHECK(REGEXP_LIKE(region_code,'^[A-Z0-9-]{2,16}$','c')),CONSTRAINT ck_flash_sale_activity_currency CHECK(REGEXP_LIKE(currency,'^[A-Z]{3}$','c')),CONSTRAINT ck_flash_sale_activity_price CHECK(sale_price_minor>=0),CONSTRAINT ck_flash_sale_activity_stock CHECK(total_stock>0 AND allocated_stock BETWEEN 0 AND total_stock),CONSTRAINT ck_flash_sale_activity_status CHECK(status IN ('draft','active','cancelled','ended')),CONSTRAINT ck_flash_sale_activity_window CHECK(starts_at<ends_at),CONSTRAINT ck_flash_sale_activity_timeout CHECK(payment_timeout_seconds BETWEEN 60 AND 86400),CONSTRAINT ck_flash_sale_activity_version CHECK(version>=0),CONSTRAINT fk_flash_sale_activity_edition FOREIGN KEY(edition_id) REFERENCES game_edition(id) ON DELETE RESTRICT,CONSTRAINT fk_flash_sale_activity_creator FOREIGN KEY(created_by) REFERENCES user_account(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARACTER SET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
